const progressKey='hk-account6-bible-champions-progress-v1';
function loadProgress(){try{const v=JSON.parse(localStorage.getItem(progressKey)||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{};}catch{return {};}}
let progress=loadProgress(),completedRecorded=false;
const historyKey='hk-account6-bible-champions-history-v1';
const sevenDays=7*24*60*60*1000;
function readHistory(){try{const data=JSON.parse(localStorage.getItem(historyKey)||'[]');return Array.isArray(data)?data.filter(r=>r&&Number.isFinite(r.time)&&r.time<=Date.now()&&r.time>=Date.now()-sevenDays&&typeof r.topic==='string'&&Number.isFinite(r.score)&&Number.isFinite(r.total)):[];}catch{return [];}}
function saveResult(){if(completedRecorded||!topic||!sessionQuestions.length)return;completedRecorded=true;const percentage=Math.round(score/sessionQuestions.length*100);const previous=progress[topic];if(!previous||percentage>previous.percent)progress[topic]={percent:percentage,score,total:sessionQuestions.length};try{localStorage.setItem(progressKey,JSON.stringify(progress));const history=readHistory();history.push({time:Date.now(),topic,score,total:sessionQuestions.length,percent:percentage});localStorage.setItem(historyKey,JSON.stringify(history.slice(-150)));}catch{}}
function historyView(){app.replaceChildren();app.append(soundControl(),el('h2','My progress — last 7 days'));const records=readHistory().sort((a,b)=>b.time-a.time);if(!records.length)app.append(el('p','No completed Bible knowledge courses recorded in the last seven days. Complete a course to begin tracking your progress.','quiz-muted'));else{const total=records.reduce((n,r)=>n+r.percent,0);app.append(el('p',records.length+' completed attempts · Average score '+Math.round(total/records.length)+'%','quiz-muted'));const list=el('div',undefined,'quiz-history');for(const r of records){const entry=el('div',undefined,'quiz-history-entry');entry.append(el('strong',r.topic),el('span',r.score+' / '+r.total+' correct ('+r.percent+'%)'),el('small',new Date(r.time).toLocaleString()));list.append(entry);}app.append(list);}app.append(button('Back to courses',home));}

const masteredTopics=()=>Object.keys(BANK).filter(k=>BANK[k].length>=30&&progress[k]?.percent>=90);
function printReportCard(){if(!topic||index<sessionQuestions.length||!sessionQuestions.length)return;const w=window.open('','_blank','width=850,height=650');if(!w){alert('Allow pop-ups to print your report card.');return;}const doc=w.document;doc.title='Bible Champions — Course Report Card';const style=doc.createElement('style');style.textContent='body{font-family:Georgia,serif;color:#17375e;margin:35px auto;max-width:720px;padding:20px;line-height:1.6}article{border:4px solid #153b73;padding:30px}h1{text-align:center}dt{font-weight:bold;margin-top:14px}dd{margin-left:0}.note{font:12px Arial;color:#666}@media print{button{display:none}}';doc.head.append(style);const article=doc.createElement('article');const heading=doc.createElement('h1');heading.textContent='Bible Champions — Report Card';article.append(heading);const details=[['Participant',address()||'Bible Champions Participant'],['Course',topic],['Correct answers',score+' of '+sessionQuestions.length],['Score',Math.round(score/sessionQuestions.length*100)+'%'],['Result',score/sessionQuestions.length>=.9?'Distinction (90% or above)':'Course completed'],['Date',new Date().toLocaleDateString()]];const dl=doc.createElement('dl');for(const [label,value] of details){const dt=doc.createElement('dt');dt.textContent=label;const dd=doc.createElement('dd');dd.textContent=value;dl.append(dt,dd);}article.append(dl);const note=doc.createElement('p');note.className='note';note.textContent='Self-generated learning record from this browser session; not independently verified or accredited.';article.append(note);doc.body.append(article);const print=doc.createElement('button');print.textContent='Print or Save as PDF';print.onclick=()=>w.print();doc.body.append(print);}

function liveScore(){const section=el('div',undefined,'quiz-scoreboard');section.setAttribute('aria-live','polite');section.append(el('strong','Live score: '+score+' / '+sessionQuestions.length),el('span','Answered: '+Math.min(index+(answered?1:0),sessionQuestions.length)+' / '+sessionQuestions.length),el('span','Topics mastered: '+masteredTopics().length+' / '+Object.keys(BANK).length));return section;}
function certificate(){if(sessionQuestions.length!==30||score<27)return;const recipient=address()||'Bible Champions Participant';const w=window.open('','_blank','width=900,height=680');if(!w){alert('Allow pop-ups to print your certificate.');return;}const doc=w.document;doc.title='Bible Champions — '+topic+' Certificate';const style=doc.createElement('style');style.textContent='body{font-family:Georgia,serif;color:#17375e;text-align:center;padding:7vw 5vw;background:#fff}article{border:10px double #b89a4e;padding:55px 25px;max-width:900px;margin:auto}h1{font-size:2.6rem}h2{font-size:1.7rem}p{line-height:1.7}.name{font-size:2rem;color:#6c521d;font-weight:bold;overflow-wrap:anywhere}.note{font:12px Arial;color:#666;margin-top:28px}@media print{body{padding:0}article{break-inside:avoid}}';doc.head.append(style);const article=doc.createElement('article');for(const [tag,txt,cls] of [['h1','Bible Champions',''],['h2','Certificate of Bible Knowledge Achievement',''],['p','Presented to',''],['p',recipient,'name'],['p','Course: '+topic,''],['p','Achievement: '+score+' correct answers out of 30 ('+Math.round(score/30*100)+'%)',''],['p','Issued '+new Date().toLocaleDateString(undefined,{year:'numeric',month:'long',day:'numeric'}),''],['p','Self-generated course achievement based on this browser session; not independently verified or accredited.','note']]){const e=doc.createElement(tag);e.textContent=txt;if(cls)e.className=cls;article.append(e);}doc.body.append(article);const print=doc.createElement('button');print.textContent='Print or Save as PDF';print.onclick=()=>w.print();doc.body.append(print);w.focus();}

async function shareBibleResult(){
 const summary='Bible Champions — '+topic+'\\nMy result: '+score+' / '+sessionQuestions.length+'\\n'+location.origin+'/bible-champions-embed.html';
 try{if(navigator.share){await navigator.share({title:'Bible Champions',text:summary,url:location.origin+'/bible-champions-embed.html'});return;}}catch(e){if(e?.name==='AbortError')return;}
 try{await navigator.clipboard.writeText(summary);alert('Bible Champions result copied. Share it using any app you choose.');}catch{window.prompt('Copy your result to share:',summary);}
}
function home(){app.replaceChildren();app.append(soundControl());const h=el('h2','GET STARTED — Choose a Bible knowledge topic');app.append(h,el('p','No account or login required. Your preferred name and title are used only during this challenge.','quiz-muted'));const profile=el('div',undefined,'quiz-profile');const titles=el('select');titles.setAttribute('aria-label','Preferred title');for(const t of ['No title','Brother','Sister','Mr.','Mrs.','Miss','Apostle','Elder','Pastor','Prophet','Teacher','Evangelist','Kingdom Financier','Revivalist','Governor','President','Senator','His Excellency','Her Excellency']){const o=el('option',t);o.value=t==='No title'?'':t;titles.append(o);}titles.value=title;titles.addEventListener('change',()=>title=titles.value);const input=el('input');input.placeholder='Your name (optional)';input.maxLength=40;input.setAttribute('aria-label','Display name (optional)');input.value=name;input.addEventListener('input',()=>name=input.value.trim().replace(/\s+/g,' '));const nameLabel=el('label','Your name (optional)');nameLabel.append(input);const titleLabel=el('label','How should we address you?');titleLabel.append(titles);profile.append(nameLabel,titleLabel);app.append(button('View my last 7 days of progress',historyView),profile,el('p','Your best topic scores are saved only in this browser. Each topic is a course. Every completed practice session earns a learning report card. Certificates require a full course of 30 distinct verified questions and a score of 90% or higher.','quiz-muted'));const list=el('div',undefined,'quiz-topics');for(const [key,questions] of Object.entries(BANK))list.append(button(key+' · '+questions.length+' / 30 questions'+(questions.length<30?' · Guided practice':' · Certificate course'),()=>startTopic(key)));app.append(list);}
function render(){app.replaceChildren();app.append(soundControl());answered=false;const q=sessionQuestions;if(!BANK[topic]){home();return;}if(index>=q.length){saveResult();app.append(liveScore());app.append(el('div','🏆','quiz-celebration'),el('h2','Challenge completed!'),el('p',(address()?address()+', ':'')+'you scored '+score+' out of '+q.length+'.'));app.append(el('h3','Your '+topic+' report card'),el('p','Result: '+score+' / '+q.length+' · '+Math.round(score/q.length*100)+'%'),el('p',score/q.length>=.9?'Excellent progress! Keep studying and growing.':'Keep studying God’s Word. You can retake this course and improve.','quiz-muted'));if(q.length===30&&score>=27)app.append(button('Print this course certificate',certificate));else if(q.length<30)app.append(el('p','This course is still being expanded to 30 unique questions. Certificates will be available once complete.','quiz-muted'));else app.append(el('p','Score at least 27 out of 30 to earn this course certificate.','quiz-muted'));app.append(button('Print my course report card',printReportCard));app.append(button('Share my result outside Bible Champions',shareBibleResult));app.append(button('View my last 7 days of progress',historyView));app.append(button('Try this challenge again',()=>startTopic(topic)),button('Choose another topic',home));playCue('complete');return;}const bar=el('div',undefined,'quiz-progress');const fill=el('div',undefined,'quiz-progress-fill');fill.style.width=(index/q.length*100)+'%';bar.append(fill);app.append(liveScore());app.append(el('p',topic+' · Question '+(index+1)+' of '+q.length,'quiz-muted'),bar,el('h2',q[index][0]));const choices=el('div',undefined,'quiz-choices');choices.setAttribute('role','group');choices.setAttribute('aria-label','Answer choices');q[index][1].forEach((value,i)=>choices.append(button(String.fromCharCode(65+i)+'. '+value,()=>answer(i))));app.append(choices,button('Change topic',home,'quiz-link'));}
function answer(chosen){if(answered)return;answered=true;const q=sessionQuestions[index],correct=chosen===q[2];if(correct)score++;const board=app.querySelector('.quiz-scoreboard');if(board)board.replaceWith(liveScore());playCue(correct?'correct':'incorrect');app.querySelectorAll('.quiz-choices button').forEach((b,i)=>{b.disabled=true;if(i===q[2])b.classList.add('quiz-answer-correct');else if(i===chosen)b.classList.add('quiz-answer-incorrect');});const result=el('section',undefined,'quiz-result '+(correct?'quiz-correct':'quiz-wrong'));result.setAttribute('role','status');result.append(el('div',correct?'🎉':'✕','quiz-result-icon'),el('h3',correct?('Congratulations'+(address()?', '+address():'')+'!'):('Not quite'+(address()?', '+address():'')+'. Don’t give up!')),el('p',correct?'🎊 Excellent! Keep going.':'Keep trying. Every question is an opportunity to learn.'),el('p','Correct answer: '+q[1][q[2]]),el('p','KJV reference: '+q[3]));result.append(button(index===sessionQuestions.length-1?'See my results':'Next question',()=>{if(index>=sessionQuestions.length)return;index++;render();const heading=app.querySelector('h2');if(heading){heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});heading.scrollIntoView?.({block:'start',behavior:'instant'});}if(index<sessionQuestions.length)playCue('question');}));app.append(result);if(!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)result.scrollIntoView?.({block:'nearest',behavior:'smooth'});}
